css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px 12px; margin-bottom: 10px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12.5px; margin-bottom: 4px; line-height: 1.35;}
.mz .recuerda-idea strong{font-weight: 700;}
.mz .recuerda-meses{display: grid; grid-template-columns: repeat(6, 1fr); gap: 4px; margin-top: 6px;}
.mz .rm-mes{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 2px; text-align: center; font-size: 11.5px; font-weight: 700; display: flex; flex-direction: column; align-items: center;}
.mz .rm-num{font-family: sans-serif; font-size: 9.5px; font-weight: 700; color: #555;}
.mz .numerar-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px 18px;}
.mz .numerar-fila{display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 600;}
.mz .numerar-hueco{width: 34px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px; flex-shrink: 0;}
.mz .ordenar-fila{display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px; margin-bottom: 5px;}
.mz .ordenar-caja{border: 1.5px solid var(--bosque); border-radius: 6px; min-height: 36px; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; text-align: center; padding: 3px;}
.mz .ordenar-caja.lleno{background: #f4f4f4;}
.mz .rodear-fila{display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px; margin-bottom: 5px;}
.mz .rodear-caja{border: 1.5px dashed #000; border-radius: 50px; padding: 8px 2px; text-align: center; font-size: 12px; font-weight: 700;}
.mz .frases{display: flex; flex-direction: column; gap: 6px;}
.mz .frase{font-size: 13px; line-height: 1.45;}
.mz .hueco-linea{display: inline-block; min-width: 110px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: bottom; margin: 0 3px;}
.mz .frase,.mz .recuerda-idea{line-height: 1.875 !important;}
